import {select,execute} from './db.mjs';

// Binary storage contract. Keys are opaque, generated by the service, never paths.
// A future object-storage adapter can coexist with mysql for gradual migration.
const stores=new Map([['mysql',{
  async put({key,bytes}){await execute('INSERT INTO avatar_blobs(storage_key,content) VALUES (?,?)',[key,bytes]);},
  async get(key){const [row]=await select('SELECT content FROM avatar_blobs WHERE storage_key=?',[key]);return row?.content||null;},
  async delete(key){await execute('DELETE FROM avatar_blobs WHERE storage_key=?',[key]);}
}]]);
export function registerAvatarStore(name,adapter){
  if(!/^[a-z][a-z0-9_-]{0,31}$/.test(name)||stores.has(name)||!['put','get','delete'].every(k=>typeof adapter?.[k]==='function'))throw Error('Invalid or duplicate avatar storage adapter');
  stores.set(name,adapter);
}
export function avatarStore(name){const store=stores.get(name);if(!store)throw Error(`Avatar storage adapter is not registered: ${name}`);return store;}
